// Uniformly sample a disk using concentric mapping
float r = std::sqrt(u[0]);
float theta = 2 * std::acos(-1) * u[1];

// Convert to Cartesian coordinates on the disk
float x = r * std::cos(theta);
float y = r * std::sin(theta);

// Project disk sample up to hemisphere: z = sqrt(1 - x^2 - y^2)
float z = std::sqrt(std::max(0.0f, 1 - x * x - y * y));

return Vector3f(x, y, z);
// END_CODE

